const themes={
 비견:{title:'네 기준은 지키고, 함께할 일은 몫을 나눠라.',summary:'이 풀이에서는 네 판단과 함께하는 사람들 사이의 균형을 잡는 게 중요해. 혼자 정할 일은 분명히 정하고, 같이 하는 일은 서로 뜻을 맞춰라.',caution:'네 방식만 옳다고 밀어붙이지 마라. 남과 비교하느라 정작 네가 원하는 걸 놓칠 필요는 없어.',
  money:advice('남이 쓴다고 네 돈까지 따라 쓰지는 마라.','뭘 살 건지, 얼마까지 쓸 건지 먼저 정해라. 남의 기준에 맞출 필요는 없어.','비교하는 마음에 필요 없는 물건까지 사지는 마라.'),
  work:advice('혼자 맡을 일과 같이 할 일을 먼저 나눠라.','누가 일을 맡고 마지막 결정은 누가 하는지 시작 전에 확인해라. 그래야 네 몫도 분명해져.','서로 상대가 하겠거니 넘기지 마라. 맡은 사람이 없는 일은 없는지 확인해라.'),
  relationships:advice('네 생각은 말하되, 상대의 선택도 존중해라.','의견이 다르면 꼭 지키고 싶은 조건부터 차분히 말하면 돼.','대화를 이기고 지는 문제로 만들지는 마라.'),
  love:romance('좋아하는 사이라도 네 방식만 강요하지 마라.','마음이 있다면 분명히 표현해라. 다만 상대가 어떤 답을 하든 그 선택은 존중해 줘.','함께할 시간과 각자 보낼 시간을 맞춰라. 늘 붙어 있어야만 좋은 관계인 건 아니야.','연락 횟수나 생활 방식을 혼자 정해 놓고 따르라고 하지는 마라.')},
 겁재:{title:'함께하는 일일수록 돈과 역할부터 정해라.',summary:'같이 힘을 모으는 일과 몫을 나누는 게 이 풀이의 중심이야. 친한 사이라도 누가 뭘 맡고 얼마를 낼지는 먼저 맞춰라.',caution:'분담도 정하지 않고 돈부터 쓰거나 남의 일까지 떠맡지는 마라. 처음에 말해 두는 편이 서로 편해.',
  money:advice('같이 쓰는 돈은 누가 얼마 낼지부터 정해라.','금액과 정산 날짜를 적어 둬라. 친한 사이라고 돈 이야기를 미룰 필요는 없어.','친분만 믿고 비용을 전부 대신 내주지는 마라.'),
  work:advice('같이 일한다면 담당자와 마감부터 맞춰라.','각자 할 일을 나누고 중간에 언제 확인할지도 정해 두면 돼.','동료에게 뒤지기 싫다고 감당 못 할 일까지 맡지는 마라.'),
  relationships:advice('도와줄 수 있는 데까지 먼저 말해라.','부탁을 받으면 할 수 있는 것과 어려운 걸 나눠서 답해라. 다 해주지 못해도 괜찮아.','거절하기 미안하다고 무조건 알겠다고 하지는 마라.'),
  love:romance('돈 문제와 주변 사람 문제는 서로 선을 맞춰라.','남들 만나는 속도에 맞춰 네 관계까지 서두르지는 마라.','데이트 비용이나 서로의 친구 관계에서 불편한 점이 있다면 말로 맞춰라.','질투가 난다고 상대의 연락이나 만남을 통제하지는 마라.')},
 식신:{title:'크게 벌이기보다 하나라도 끝내라.',summary:'이 풀이에서는 꾸준히 손을 움직여 결과를 남기는 걸 중심으로 보면 돼. 계획을 더 보태기 전에 시작한 것 하나부터 마무리해라.',caution:'시작만 늘리고 끝내는 일을 뒤로 미루지는 마라. 작은 것 하나라도 마무리하는 데 힘을 써라.',
  money:advice('작게 자꾸 나가는 돈부터 챙겨라.','최근에 습관처럼 결제한 게 뭔지 찾아 정리해라. 큰돈만 볼 일은 아니야.','한 번에 얼마 안 된다고 쌓이는 금액까지 무시하지는 마라.'),
  work:advice('계획서보다 끝낸 일 하나를 남겨라.','짧게 끝낼 수 있는 단위로 나눠 하나씩 마무리해서 내면 돼.','여러 일을 한꺼번에 벌이다 마감을 놓치지는 마라.'),
  relationships:advice('작은 약속부터 꾸준히 지켜라.','안부를 묻거나 도와주기로 했다면 실제로 움직여라. 큰 말보다 그런 행동이 중요해.','좋은 마음으로 한 약속도 잊은 채 넘기지는 마라.'),
  love:romance('큰 이벤트보다 꾸준히 마음을 보여라.','부담 없는 대화와 만남부터 이어가라. 서로 알아갈 시간을 가지면 돼.','연락과 함께 보내기로 한 시간을 꾸준히 지켜라.','못 지킬 큰 약속으로 마음을 증명하려 하지는 마라.')},
 상관:{title:'할 말은 하되, 어떻게 말할지 한 번 더 생각해라.',summary:'이 풀이의 중심은 표현과 방식의 변화야. 바꾸고 싶은 게 있다면 문제만 짚지 말고 어떻게 바꾸자는 건지도 같이 말해라.',caution:'감정이 앞선 말이나 공개적인 비판은 조심해라. 하고 싶은 말과 상처 주는 말은 구분할 필요가 있어.',
  money:advice('새로 나왔다고 바로 사지는 마라.','어디에 쓸 건지, 이미 가진 걸로 대신할 수는 없는지 먼저 확인해라.','기분을 풀겠다고 계획에 없던 돈을 쓰지는 마라.'),
  work:advice('문제를 꺼낼 때는 해결 방법도 같이 내놔라.','어디를 어떻게 바꾸자는 건지 짧게 정리해서 말하면 돼.','사람들 앞에서 상대나 조직을 깎아내리는 말은 삼가라.'),
  relationships:advice('상대를 지적하기보다 네가 바라는 걸 말해라.','어떤 상황이 불편했는지, 다음에는 어떻게 해줬으면 하는지 구체적으로 말해라.','비꼬거나 원래 그런 사람이라고 단정하지는 마라.'),
  love:romance('속마음은 솔직하게, 말은 다정하게 해라.','마음과 의도는 분명히 말하되 답을 재촉하지는 마라.','서운했던 일과 바라는 변화를 하나씩 꺼내라. 한꺼번에 쏟아낼 필요는 없어.','떠보는 말이나 비꼬는 말, 다른 사람과 비교하는 말은 조심해라.')},
 편재:{title:'새 제안은 반가워도 시간과 비용부터 따져라.',summary:'바깥 활동과 자원을 어디에 쓸지가 이 풀이의 중심이야. 제안이 들어오면 왜 참여하는지, 실제로 얼마나 부담해야 하는지부터 확인해라.',caution:'좋아 보인다는 이유만으로 돈이나 시간을 약속하지 마라. 조건부터 확인해도 늦지 않아.',
  money:advice('새로 쓸 돈은 끝까지 얼마 드는지 계산해라.','처음 내는 돈과 계속 들어갈 돈을 나눠 적어 봐라.','돈이 된다는 말만 듣고 바로 결제하지는 마라.'),
  work:advice('새 일은 얻을 경험과 들일 시간을 같이 봐라.','어디까지 해야 하는지, 언제까지인지, 뭐가 필요한지 확인하고 맡아라.','하던 일이 남았는데 새 제안을 모두 받아들이지는 마라.'),
  relationships:advice('새로 만난 사람에게도 약속은 가능한 만큼만 해라.','관심사는 편하게 나누되 도와줄 수 있는지, 참여할 수 있는지는 따로 판단해라.','첫인상이 좋다고 곧바로 전부 믿지는 마라.'),
  love:romance('마음이 끌리는 것과 확신이 드는 건 구분해라.','한 번 만났다고 관계를 단정하지 마라. 말과 행동이 같은지 알아갈 시간을 가져라.','새로운 걸 함께할 때는 쓸 돈과 시간을 먼저 맞춰라.','잘 보이고 싶다고 무리한 선물이나 지출을 하지는 마라.')},
 정재:{title:'새는 돈과 밀린 일부터 차근차근 정리해라.',summary:'이 풀이에서는 지금 가진 것과 일상을 꾸준히 관리하는 데 무게를 둬. 새 일을 보태기 전에 반복해서 나가는 돈과 미뤄 둔 일부터 챙겨라.',caution:'안 쓰는 정기 결제나 지키기 벅찬 약속을 그냥 두지는 마라. 계속 가져갈 것부터 추려라.',
  money:advice('매달 나가는 돈부터 정리해라.','정기 결제와 납부 목록을 펼쳐 놓고 안 쓰는 게 없는지 확인해라.','작은 자동 결제라고 계속 쌓이게 두지는 마라.'),
  work:advice('늘 하던 일일수록 빠뜨린 게 없는지 챙겨라.','마감 목록과 확인 순서를 정하고 밀린 것부터 끝내면 돼.','익숙한 일이라고 확인도 없이 넘기지는 마라.'),
  relationships:advice('지킬 수 있는 약속만 해라.','연락이나 모임은 실제로 낼 수 있는 시간 안에서 정해라. 무리해서 맞출 필요는 없어.','약속을 취소할 때는 이유를 말해 줘라. 설명 없이 넘기지는 마라.'),
  love:romance('일상에서 지킬 수 있는 애정을 쌓아라.','서로 언제 쉬고 어떻게 연락하는지 알아가라. 생활 리듬도 맞춰 볼 부분이야.','함께할 시간이나 생활비처럼 반복되는 약속을 확인해라.','익숙한 사이라고 표현과 배려까지 생략하지는 마라.')},
 편관:{title:'급한 일부터 골라라. 모든 짐을 혼자 질 필요는 없어.',summary:'이 풀이에서는 해야 할 일과 감당할 몫을 나누는 게 중요해. 혼자 끝낼 수 없는 일은 도움을 구하거나 기한을 조정해라.',caution:'마음이 급하다고 일도 돈도 약속도 바로 받아들이지는 마라. 감당할 수 있는지부터 확인해라.',
  money:advice('돈을 빨리 내라고 해도 조건부터 봐라.','꼭 필요한 지출인지, 금액과 기한이 맞는지 확인하고 결정해라.','지금 아니면 안 된다는 압박에 끌려 돈을 쓰지는 마라.'),
  work:advice('마감이 겹치면 무엇부터 할지 먼저 맞춰라.','먼저 끝낼 일을 고르고 나머지는 기한이나 도와줄 사람을 조정해라.','감당 못 할 일까지 혼자 다 하겠다고 약속하지 마라.'),
  relationships:advice('버거운 부탁은 해줄 수 있는 만큼으로 줄여라.','할 수 있는 도움과 어려운 도움을 나눠 말해라. 네 사정도 중요해.','미안함이나 압박 때문에 원치 않는 약속을 하지는 마라.'),
  love:romance('마음이 급해도 상대를 몰아붙이지 마라.','답장이나 만남을 강요하지 말고 싫다는 뜻은 존중해라.','연락과 함께할 시간, 서로의 역할에서 기대가 너무 크지는 않은지 맞춰라.','불안하다고 계속 확인하거나 상대를 통제하지는 마라.')},
 정관:{title:'어디까지 네 몫인지, 언제까지 할 건지 먼저 정해라.',summary:'이 시기는 맡은 몫과 약속을 중심으로 읽으면 돼. 어디까지 해야 끝난 건지 먼저 확인하고, 정한 일정과 약속은 차근차근 지켜라.',caution:'기준도 모른 채 책임부터 맡지는 마라. 지키기 어려운 약속까지 보탤 필요는 없어.',
  money:advice('내기로 한 돈과 날짜부터 챙겨라.','얼마를 언제 내는지, 누구와 나눠 내는지 적어 두면 돼.','내용도 읽지 않고 비용을 부담하겠다고 하지는 마라.'),
  work:advice('어디까지 네 일인지 먼저 정해라.','언제까지 무엇을 끝내야 하는지 확인해라. 중간에 달라진 내용은 적어 둬라.','남의 일까지 설명 없이 떠안지는 마라. 혼자 다 책임질 필요는 없어.'),
  relationships:advice('서로 어떤 약속을 한 건지 말로 맞춰라.','누가 무엇을 언제까지 할지 구체적으로 정하면 돼.','네 기준을 상대도 당연히 알 거라고 생각하지는 마라.'),
  love:romance('서로 바라는 관계가 같은지 이야기해라.','어떤 관계를 원하는지 마음을 나눠라. 혼자 짐작할 필요는 없어.','연락과 만남, 앞으로의 계획에서 서로 기대하는 게 같은지 확인해라.','말로 정하지도 않은 기대를 약속처럼 여기고 상대를 평가하지는 마라.')},
 편인:{title:'막히면 방법을 바꿔라. 하나는 직접 해봐야 해.',summary:'다른 관점으로 보고 길을 찾는 게 이 풀이의 중심이야. 자료를 더 모으는 데서 멈추지 말고, 새 방법 하나는 실제로 해봐라.',caution:'짐작을 사실로 여기거나 준비만 하다 실행을 미루지는 마라. 확인할 건 확인하고 작게라도 움직여라.',
  money:advice('강의나 도구는 언제 쓸 건지부터 정해라.','왜 필요한지, 실제로 쓸 시간이 있는지 확인하고 결제해라.','배우고 싶다는 마음만으로 강의나 자료를 계속 사지는 마라.'),
  work:advice('방법을 하나 바꿔서 작은 일부터 해봐라.','하던 방식이 막혔다면 다른 방법 하나를 골라 직접 확인하면 돼.','조사만 반복하면서 결정과 실행을 뒤로 미루지는 마라.'),
  relationships:advice('상대의 속마음을 혼자 단정하지 마라.','이해가 안 되는 행동은 왜 그랬는지 직접 물어봐라.','답이 늦다는 이유만으로 마음이나 의도를 짐작해서 결론 내리지는 마라.'),
  love:romance('혼자 짐작하지 말고 직접 이야기해라.','짧은 메시지 하나만 보고 마음이 있다 없다 단정하지는 마라.','혼자 생각할 시간이 필요하면 이유와 언제 다시 이야기할지 알려 줘라.','말하지 않아도 알아주길 바라면서 대화까지 끊지는 마라.')},
 정인:{title:'모르는 건 물어라. 도움받을 일까지 혼자 끌어안지 마라.',summary:'배운 걸 정리하고 필요한 도움을 받는 데 초점을 두면 돼. 막힌 부분은 구체적으로 물어보고, 받은 조언을 어디에 쓸지도 정해라.',caution:'조언을 듣기만 하거나 결정을 전부 남에게 맡기지는 마라. 마지막에는 네 판단도 필요해.',
  money:advice('배우는 데 쓰는 돈도 목적부터 정해라.','그 강의나 자료가 지금 하려는 일에 필요한지 확인해라.','누가 좋다고 했다는 이유만으로 필요 없는 강의를 결제하지는 마라.'),
  work:advice('자료를 정리하고, 막힌 부분을 콕 집어 물어라.','어디서 막혔는지, 뭘 해봤는지 정리해서 도움을 구하면 돼.','받은 답은 적어 둬라. 같은 질문만 반복하고 끝내지는 마라.'),
  relationships:advice('어떤 도움이 필요한지 분명하게 말해라.','무엇을 언제까지 도와줬으면 하는지 말하고, 도움을 받았다면 고마운 마음도 전해라.','말하지 않아도 알아서 도와줄 거라고 기다리지는 마라.'),
  love:romance('도움과 애정을 구분하고, 네 마음도 표현해라.','친절하다는 이유만으로 마음이 있다고 단정하지 말고 뜻을 확인해라.','위로를 원하는 건지 해결 방법을 원하는 건지 먼저 물어라.','상대 대신 결정하거나 일방적으로 가르치려 들지는 마라.')}
};

export function plainReading(model,result){
 const segments=[];
 for(const [index,row] of result.rows.entries()){
  const god=model.common.day&&row.evidence?.god;
  const content=god?themes[god]:null;
  const previous=segments.at(-1);
  if(previous&&previous.end===row.start&&previous.god===(content?god:null)){
   previous.end=row.end;previous.sourceRows.push(index);
  }else segments.push({start:row.start,end:row.end,god:content?god:null,content:content?JSON.parse(JSON.stringify(content)):null,sourceRows:[index]});
 }
 const notes=[];
 if(!model.common.day)notes.push('출생시간에 따라 풀이의 기준이 달라져 개인별 설명을 아직 보여드릴 수 없어요. 출생기록을 확인하거나 시간 범위를 좁혀 다시 조회해 주세요.');
 else if(model.input.timeMode!=='exact'||model.candidates.length>1)notes.push('출생시간이 하나로 정해지지 않았어요. 가능한 시간에서 공통으로 확인되는 기준만으로 설명했어요.');
 if(model.nearTerms.length)notes.push('태어난 때가 계절 기준이 바뀌는 시각과 가까워요. 출생 연도·월의 사주 계산은 추가 확인이 필요해요.');
 if(!result.schedule&&model.input.sex==='unspecified')notes.push('성별을 선택하지 않아 10년 단위 흐름은 계산하지 않았어요. 성별은 출생일을 기준으로 한 기본 풀이에는 사용하지 않아요.');
 else if(!result.schedule)notes.push('출생시각을 더 확인해야 10년 단위 흐름을 계산할 수 있어요.');
 return {version:READING_VERSION,title:result.title,segments,notes,scope:'전통 해석에 따른 생활 조언입니다. 수입·승진·만남의 발생 여부나 운의 좋고 나쁨은 확정하지 않습니다. 애정은 현재 관계에 맞는 항목을 읽으세요.',status:'기초 관계 풀이 · 10년 단위 흐름 종합 전 · 전문가 검수 전'};
}
